using ManpowerManagement.Data;using ManpowerManagement.Models;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;
namespace ManpowerManagement.Pages.Tickets;
public class CreateModel(AppDbContext db):PageModel{public class InputModel{public string RequesterEmployeeId{get;set;}="";public string RequesterShift{get;set;}="Day";public int WorkshopId{get;set;}public int EmployeeId{get;set;}}[BindProperty]public InputModel Input{get;set;}=new();public List<SelectListItem> Workshops{get;set;}=[];public List<SelectListItem> Employees{get;set;}=[];[TempData]public string? Message{get;set;}public async Task OnGetAsync()=>await Load();public async Task<IActionResult> OnPostAsync(){if(!await db.Employees.AnyAsync(x=>x.EmployeeId==Input.RequesterEmployeeId)){ModelState.AddModelError("Input.RequesterEmployeeId","Requester ID not found.");await Load();return Page();}db.ResignationTickets.Add(new ResignationTicket{RequesterEmployeeId=Input.RequesterEmployeeId,RequesterShift=Input.RequesterShift,WorkshopId=Input.WorkshopId,EmployeeId=Input.EmployeeId});db.AuditLogs.Add(new AuditLog{EntityName="ResignationTicket",EntityKey=Input.EmployeeId.ToString(),Action="Submitted",Actor=Input.RequesterEmployeeId});await db.SaveChangesAsync();Message="Ticket submitted.";return RedirectToPage();}async Task Load(){Workshops=await db.Workshops.OrderBy(x=>x.Name).Select(x=>new SelectListItem(x.Name,x.Id.ToString())).ToListAsync();Employees=await db.Employees.Where(x=>x.EmploymentState==EmploymentState.Active).OrderBy(x=>x.FullName).Select(x=>new SelectListItem(x.EmployeeId+" - "+x.FullName,x.Id.ToString())).ToListAsync();}}
